"use strict";

var _listsCore = require("@joltup/lists-core");
var _DateRangeFilter = require("../DateRangeFilter.utils");
describe('DateRangeFilter.utils.js', function () {
  describe('calculateDateString', function () {
    it('should return correct text for a range in the same month and year', function () {
      expect((0, _DateRangeFilter.calculateDateString)([2338207202, 2338207202])).toEqual('Feb 4');
    });
    it('should return correct full text for the same day', function () {
      expect((0, _DateRangeFilter.calculateDateString)([2338207202, 2338207202], true)).toEqual('Feb 4, 2044');
    });
    it('should return correct text for a range in the same month and year', function () {
      expect((0, _DateRangeFilter.calculateDateString)([2338207202, 2339762402])).toEqual('Feb 4 - 22');
    });
    it('should return correct text for a range in different months in the same year', function () {
      expect((0, _DateRangeFilter.calculateDateString)([2338207202, 2346760802])).toEqual('Feb 4 - May 13');
    });
    it('should return correct full text for a range in different months in the same year', function () {
      expect((0, _DateRangeFilter.calculateDateString)([2338207202, 2346760802], true)).toEqual('Feb 4, 2044 - May 13, 2044');
    });
    it('should return correct text for a range in different years', function () {
      expect((0, _DateRangeFilter.calculateDateString)([12321312321, 22321312321])).toEqual('Jun 12, 2360 - May 2, 2677');
    });
    it('should return correct text for invalid DATE_RANGE', function () {
      expect((0, _DateRangeFilter.calculateDateString)([12321312321, null])).toEqual('No Date Range Selected');
    });
  });
  describe('getButtonText', function () {
    it('should return correct text for DATE_RANGE', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_DATE_RANGE, [12321312321, 22321312321])).toEqual('Jun 12, 2360 - May 2, 2677');
    });
    it('should return correct text for invalid DATE_RANGE', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_DATE_RANGE, [12321312321, null])).toEqual('No Date Range Selected');
    });
    it('should return correct text for CALENDAR_OPTION_TODAY', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_TODAY)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_TODAY]);
    });
    it('should return correct text for CALENDAR_OPTION_YESTERDAY', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_YESTERDAY)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_YESTERDAY]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_7_DAYS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_7_DAYS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_7_DAYS]);
    });
    test('should return correct text for CALENDAR_OPTION_LAST_14_DAYS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_14_DAYS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_14_DAYS]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_30_DAYS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_30_DAYS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_30_DAYS]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_60_DAYS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_60_DAYS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_60_DAYS]);
    });
    test('should return correct text for CALENDAR_OPTION_LAST_90_DAYS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_90_DAYS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_90_DAYS]);
    });
    it('should return correct text for CALENDAR_OPTION_THIS_WEEK', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_THIS_WEEK)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_THIS_WEEK]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_WEEK', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_WEEK)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_WEEK]);
    });
    it('should return correct text for CALENDAR_OPTION_THIS_MONTH', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_THIS_MONTH)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_THIS_MONTH]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_MONTH', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_MONTH)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_MONTH]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_2_MONTHS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_2_MONTHS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_2_MONTHS]);
    });
    test('should return correct text for CALENDAR_OPTION_LAST_3_MONTHS', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_3_MONTHS)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_3_MONTHS]);
    });
    it('should return correct text for CALENDAR_OPTION_THIS_YEAR', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_THIS_YEAR)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_THIS_YEAR]);
    });
    it('should return correct text for CALENDAR_OPTION_LAST_YEAR', function () {
      expect((0, _DateRangeFilter.getButtonText)(_listsCore.CALENDAR_OPTION_LAST_YEAR)).toEqual(_listsCore.CALENDAR_OPTIONS[_listsCore.CALENDAR_OPTION_LAST_YEAR]);
    });
    it('should return correct text for an invalid option', function () {
      expect((0, _DateRangeFilter.getButtonText)('NOT A REAL CHOICE')).toEqual('Invalid Selection');
    });
  });
});